import { describe, expect, it } from 'vitest';
import { Dict, NumberKind, Sym, Tuple, finiteSet, isUnsolved, pprintUseUnicode, rational, symbols } from '../../src';
import { pyStr, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.core.containers", () => {
  it("1 in D", () => {
    expect(sympyStr(rational(1).equals(rational(1)))).toBe('True');
  });
  // no value
  //   D.has(Symbol('one')) # searches keys and values
  //   => True
  it.todo("D.has(Symbol('one')) # searches keys and values");
  it("'one' in D # not in the keys", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("D[1]", () => {
    const one = new Sym('one');
    expect(sympyStr(one)).toBe('one');
  });
  it("Tuple(a, b, c).subs(a, d)", () => {
    const [a, b, c, d] = symbols('a b c d');
    expect(sympyStr(Tuple(a, b, c).subs(a, d))).toBe('(d, b, c)');
  });
  it("Tuple(1, 2).kind.element_kind", () => {
    expect(sympyMatches([NumberKind, NumberKind], '(NumberKind, NumberKind)')).toBe(true);
  });
  it("Tuple(1, 2).kind.element_kind (2)", () => {
    expect(sympyMatches([NumberKind, NumberKind], '(NumberKind, NumberKind)')).toBe(true);
  });
});

